function getVerbStem(word, type) {
    if (type === "ichidan") {
        return word.slice(0, -1);
    } else if (type === "godan") {
        const lastChar = word.slice(-1);
        const stemMap = { 'う':'い', 'く':'き', 'ぐ':'ぎ', 'す':'し', 'つ':'ち', 'ぬ':'に', 'ぶ':'び', 'む':'み', 'る':'り' };
        return word.slice(0, -1) + stemMap[lastChar];
    } else if (type === "irregular") {
        if (word === "する") return "し";
        if (word === "来る" || word === "くる") return word === "来る" ? "来" : "き";
    }
    return word;
}

function initGrammarSection() {
    const select = document.getElementById('verb-dropdown');
    if (!select) return;
    
    // Svuota il menu prima di riempirlo (evita duplicati)
    select.innerHTML = '<option value="">Seleziona un verbo...</option>';

    verbDatabase.forEach(verb => {
        const option = document.createElement('option');
        option.value = verb.id;
        option.textContent = `${verb.kanji} (${verb.it})`;
        select.appendChild(option);
    });
}

function generateConjugations() {
    const select = document.getElementById('verb-dropdown');
    const verbId = select.value;
    const board = document.getElementById('conjugation-board');
    
    if (!verbId) {
        board.style.display = 'none';
        return;
    }
    
    const verb = verbDatabase.find(v => v.id == parseInt(verbId));
    board.style.display = 'block';
    
    const stemKanji = getVerbStem(verb.kanji, verb.type);
    const stemKana = getVerbStem(verb.kana, verb.type);
    
    const formatConj = (suffix) => `${stemKanji}${suffix} (${stemKana}${suffix})`;
    
    document.getElementById('conj-pres-pos').textContent = formatConj("ます");
    document.getElementById('conj-pres-neg').textContent = formatConj("ません");
    document.getElementById('conj-past-pos').textContent = formatConj("ました");
    document.getElementById('conj-past-neg').textContent = formatConj("ませんでした");
    document.getElementById('conj-tai').textContent = formatConj("たい");

    document.querySelector('.conj-card.positive .it-translation').textContent = verb.it_pres;
    document.querySelector('.conj-card.negative .it-translation').textContent = "non " + verb.it_pres;
    document.querySelector('.conj-card.past-pos .it-translation').textContent = verb.it_past;
    document.querySelector('.conj-card.past-neg .it-translation').textContent = "non " + verb.it_past;
    document.querySelector('.conj-card.volitional .it-translation').textContent = verb.it_vol;
    
    document.getElementById('sentence-box').style.display = 'none';
}

function fetchTatoebaSentence() {
    const select = document.getElementById('verb-dropdown');
    const verbId = parseInt(select.value);
    if (!verbId) return;

    const sentences = sentenceDatabase.filter(s => s.verbId === verbId);
    if (sentences.length === 0) {
        alert("Ops! Non ho ancora aggiunto frasi per questo verbo.");
        return;
    }

    const randomSentence = sentences[Math.floor(Math.random() * sentences.length)];
    document.getElementById('ja-sentence').textContent = randomSentence.ja;
    document.getElementById('it-sentence').textContent = randomSentence.it;
    document.getElementById('ja-sentence').dataset.answer = randomSentence.answer;
    
    document.getElementById('sentence-box').style.display = 'block';
}

function revealSentenceVerb() {
    const jaSentence = document.getElementById('ja-sentence');
    const answer = jaSentence.dataset.answer;
    jaSentence.innerHTML = jaSentence.textContent.replace("[VERB]", `<strong style="color:#0066cc;">${answer}</strong>`);
}